import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';

function setup(){
 const context=vm.createContext({TextEncoder});vm.runInContext(fs.readFileSync(new URL('../ui/recovery.js',import.meta.url),'utf8'),context);
 const values=new Map();const storage={getItem:k=>values.get(k)??null,setItem:(k,v)=>values.set(k,v),removeItem:k=>values.delete(k)};
 let now=100000000;return {values,storage,factory:context.StartkompasRecovery,create:scope=>context.StartkompasRecovery(storage,scope,()=>now),advance:ms=>now+=ms};
}
const wizard={name:'Fictional studio',id:'practice',task:'Prepare an offer',customer:'Unknown customer',outcome:''};
test('tab recovery preserves exact text, isolates roots, expires, and clears without project writes',()=>{
 const s=setup(),a=s.create('root-a');assert.equal(a.read(),null);a.write('wizard',wizard);
 assert.deepEqual(JSON.parse(JSON.stringify(a.read().data)),wizard);
 assert.equal(s.create('root-b').read(),null);
 s.advance(24*60*60*1000+1);assert.equal(a.read(),null);
 a.write('wizard',wizard);a.clear();assert.equal(s.values.size,0);
});
test('recovery refuses confirmations, preview handles, invalid shapes, oversized and corrupt copies',()=>{
 const s=setup(),a=s.create('root');
 for(const data of [{...wizard,confirmed:true},{...wizard,preview:'old'}, {...wizard,customer:'x'.repeat(2001)},null])assert.throws(()=>a.write('wizard',data));
 assert.throws(()=>a.write('unexpected',wizard));
 for(const raw of ['{','null','x'.repeat(100001),JSON.stringify({scope:'root',kind:'wizard',at:100000001,data:wizard})]){s.values.set('startkompas-recovery-v1',raw);assert.equal(a.read(),null);}
});
test('offer recovery retains exact project revision and basis hash; storage failures are not reported as success',()=>{
 const s=setup(),a=s.create('root');const offer={folder:'practice',id:'practice',previous:null,revision:3,sha256:'a'.repeat(64),client:'',period:'',reason:'',fields:{segment:'Fictional',outcome:''}};
 a.write('offer',offer);assert.deepEqual(JSON.parse(JSON.stringify(a.read().data)),offer);
 for(const data of [{...offer,revision:0},{...offer,sha256:'bad'},{...offer,fields:{segment:42}},{...offer,confirmed:true}])assert.throws(()=>a.write('offer',data));
 const failed=s.factory({getItem(){throw Error('blocked');},setItem(){throw Error('quota');},removeItem(){throw Error('blocked');}},'root');
 assert.throws(()=>failed.read(),/blocked/);assert.throws(()=>failed.write('wizard',wizard),/quota/);assert.throws(()=>failed.clear(),/blocked/);
});

test('decision tab recovery retains partial text and selected context without preview authority',()=>{
 const s=setup(),a=s.create('root'),data={folder:'practice',id:'practice',previous:null,revision:2,sha256:'b'.repeat(64),basis_id:'fact-1',considered_feedback:['response-1'],fields:{choice:'Unfinished choice',reason:'',owner:'Alias',uncertainty:'Unknown',alternatives:'x'.repeat(8000),reconsider:'',date:''}};
 a.write('decision',data);assert.deepEqual(JSON.parse(JSON.stringify(a.read().data)),data);
 for(const patch of [{confirmed:true},{preview:'old'},{revision:0},{considered_feedback:['response-1','response-1']},{fields:{...data.fields,alternatives:'x'.repeat(8001)}}])assert.throws(()=>a.write('decision',{...data,...patch}));
 assert.equal(s.create('different-root').read(),null);s.advance(86400001);assert.equal(a.read(),null);
});

test('profile tab recovery preserves an unfinished answer but never a confirmation',()=>{
 const s=setup(),a=s.create('root'),data={folder:'practice',id:'practice',revision:2,sha256:'b'.repeat(64),key:'customer',value:'Unfinished customer description',date:''};
 a.write('profile',data);assert.deepEqual(JSON.parse(JSON.stringify(a.read().data)),data);
 for(const patch of [{confirmed:true},{preview:'old'},{revision:0},{key:'../other'},{value:'x'.repeat(4001)},{date:'2026-11-031'}])assert.throws(()=>a.write('profile',{...data,...patch}));
 a.write('profile',{...data,value:''});assert.equal(a.read().data.value,'');assert.equal(s.create('other-root').read(),null);
});

test('discarding another form preserves the pending copy; matching discard and explicit forget remove it',()=>{
 const s=setup(),a=s.create('root'),profile={folder:'practice',id:'practice',revision:2,sha256:'b'.repeat(64),key:'constraints',value:'Unfinished answer',date:''};
 for(const [kind,data] of [['wizard',wizard],['profile',profile],['offer',{folder:'practice',id:'practice',previous:null,revision:2,sha256:'b'.repeat(64),client:'',period:'',reason:'',fields:{segment:'Unfinished'}}]]){
  a.write(kind,data);const raw=[...s.values.values()][0];
  for(const other of ['wizard','profile','offer','decision'].filter(value=>value!==kind)){assert.equal(a.clear(other),false);assert.equal([...s.values.values()][0],raw);}
  assert.equal(a.clear(kind),true);assert.equal(a.read(),null);
 }
 a.write('profile',profile);assert.equal(s.create('other-root').clear('profile'),false);assert.equal(a.read().data.value,profile.value);
 assert.equal(a.clear(),true);assert.equal(s.values.size,0);
});

