function packageRestoreHarness({changed=false,archived=false,missing=false,raced=false}={}){
 const source=fs.readFileSync(new URL('../ui/ui.js',import.meta.url),'utf8'),start=source.indexOf(" if(entry.kind==='review-package'){",source.indexOf('async function applyRecoveredEntry')),end=source.indexOf(" if(entry.kind==='experiment-review'){",start);
 const nodes=new Map(),inputs=[{dataset:{document:'offer-1'},value:'delivery',checked:false},{dataset:{document:'offer-2'},value:'delivery',checked:true}];
 const node=id=>{if(!nodes.has(id))nodes.set(id,{value:'',textContent:'',hidden:false,checked:true,querySelectorAll:()=>missing?inputs.slice(1):inputs});return nodes.get(id);};
 const data={folder:'practice',id:'practice',revision:3,sha256:'c'.repeat(64),fields:{name:'',owner:'',reviewer:'',questions:'  Raw question\n'},sections:[{document:'offer-1',key:'delivery'}]},state={sha256:raced?'d'.repeat(64):data.sha256,preview:'old'};
 const context=vm.createContext({$:node,projectList:[{folder:data.folder,id:data.id,ref:'project-ref'}],currentView:{revision:changed?4:3,sha256:data.sha256,archived},reviewPackageState:state,reviewPackageDirty:false,show:async()=>{},openReviewPackage:async()=>{},notice:()=>{}});vm.runInContext('async function restore(entry){const d=entry.data;'+source.slice(start,end)+'}',context);return {data,state,inputs,node,context,restore:()=>context.restore({kind:'review-package',data})};
}
test('review-package editor restores only exact document-section pairs and requires fresh confirmation',async()=>{const h=packageRestoreHarness();await h.restore();assert.deepEqual(h.inputs.map(i=>i.checked),[true,false]);assert.equal(h.node('review-package-questions').value,h.data.fields.questions);assert.equal(h.node('review-package-owner').value,'');assert.equal(h.state.preview,null);assert.equal(h.node('review-package-confirm').checked,false);assert.equal(h.node('review-package-preview').hidden,true);assert.equal(h.context.reviewPackageDirty,true);});
test('review-package editor refuses stale or missing context and leaves readable recovery text',async()=>{for(const options of [{changed:true},{archived:true},{missing:true},{raced:true}]){const h=packageRestoreHarness(options);await assert.rejects(h.restore());assert.equal(h.context.reviewPackageDirty,false);assert.equal(h.node('recovery-text').hidden,false);assert.deepEqual(h.inputs.map(i=>i.checked),[false,true]);}});

