 const source=fs.readFileSync(new URL('../ui/ui.js',import.meta.url),'utf8'),start=source.indexOf(" if(entry.kind==='review-feedback'){",source.indexOf('async function applyRecoveredEntry')),end=source.indexOf(" if(entry.kind==='review-package'){",start);
