function reportRestoreHarness({changed=false,raced=false,missing=false}={}){
 const source=fs.readFileSync(new URL('../ui/ui.js',import.meta.url),'utf8'),start=source.indexOf(" if(entry.kind==='report'){",source.indexOf('async function applyRecoveredEntry')),end=source.indexOf(" if(entry.kind==='support'){",start),inputs=[{value:'summary',checked:true},{value:'tasks',checked:true},{value:'assumptions',checked:false}],nodes=new Map(),node=id=>{if(!nodes.has(id))nodes.set(id,{value:'',textContent:'',hidden:false,checked:true,querySelectorAll:()=>missing?inputs.slice(0,2):inputs});return nodes.get(id);};
 const data={folder:'practice',id:'practice',revision:3,sha256:'c'.repeat(64),sections:['assumptions']},state={sha256:raced?'d'.repeat(64):data.sha256,preview:'old'},context=vm.createContext({$:node,projectList:[{folder:data.folder,id:data.id,ref:'project-ref'}],currentView:{revision:changed?4:3,sha256:data.sha256},reportState:state,reportDirty:false,show:async()=>{},openReport:async()=>{},notice:()=>{}});vm.runInContext('async function restore(entry){const d=entry.data;'+source.slice(start,end)+'}',context);return {data,state,node,inputs,context,restore:sections=>context.restore({kind:'report',data:{...data,sections:sections??data.sections}})};
}
test('report restoration clears default sections and all approval for exact recovered selections',async()=>{for(const sections of [[],['assumptions']]){const h=reportRestoreHarness();await h.restore(sections);assert.deepEqual(h.inputs.filter(i=>i.checked).map(i=>i.value),sections);assert.equal(h.state.preview,null);assert.equal(h.node('report-confirm').checked,false);assert.equal(h.context.reportDirty,true);}});
test('report restoration refuses changed context or unavailable sections without altering defaults',async()=>{for(const options of [{changed:true},{raced:true},{missing:true}]){const h=reportRestoreHarness(options);await assert.rejects(h.restore());assert.equal(h.context.reportDirty,false);assert.equal(h.node('recovery-text').hidden,false);assert.deepEqual(h.inputs.map(i=>i.checked),[true,true,false]);}});

test('report PDF refuses a newer project before decoding or presenting export bytes',async()=>{
 const source=fs.readFileSync(new URL('../ui/ui.js',import.meta.url),'utf8'),start=source.indexOf('async function openPdf('),end=source.indexOf("$('report-pdf')",start),context=vm.createContext({clearPdf(){},api:async()=>({project_sha256:'changed'}),selected:'ref',reportState:{sha256:'original'}});vm.runInContext(source.slice(start,end),context);await assert.rejects(context.openPdf({kind:'report',sections:['tasks']},'report','Report'),/project changed/);
});

test('external-summary recovery preserves exact original and custom section choices without approval',()=>{const a=setup().create('root'),base={folder:'practice',id:'practice',revision:3,sha256:'c'.repeat(64),artifact_id:'offer-1',keys:[]};for(const keys of [[],['delivery','custom_owner']]){a.write('summary',{...base,keys});assert.deepEqual(JSON.parse(JSON.stringify(a.read().data.keys)),keys);}for(const patch of [{confirmed:true},{preview:'old'},{keys:['delivery','delivery']},{artifact_id:'../other'},{keys:['x'.repeat(101)]}])assert.throws(()=>a.write('summary',{...base,...patch}));});
function externalSummaryRestoreHarness({changed=false,raced=false,missing=false,historical=false}={}){
 const source=fs.readFileSync(new URL('../ui/ui.js',import.meta.url),'utf8'),start=source.indexOf(" if(entry.kind==='summary'){",source.indexOf('async function applyRecoveredEntry')),end=source.indexOf(" if(entry.kind==='report'){",start),inputs=[{value:'delivery',checked:false},{value:'custom_owner',checked:false}],nodes=new Map(),node=id=>{if(!nodes.has(id))nodes.set(id,{value:'',textContent:'',hidden:false,checked:true,querySelectorAll:()=>missing?inputs.slice(0,1):inputs});return nodes.get(id);};
 const data={folder:'practice',id:'practice',revision:3,sha256:'c'.repeat(64),artifact_id:'offer-1',keys:['custom_owner']},state={preview:'old'},requests=[],context=vm.createContext({$:node,selected:'project-ref',projectList:[{folder:data.folder,id:data.id,ref:'project-ref'}],currentView:{revision:changed?4:3,sha256:data.sha256},summaryState:state,summaryDirty:false,show:async()=>{},api:async(route,input)=>{requests.push([route,input.id]);return {id:data.artifact_id,kind:'offer',sha256:raced?'d'.repeat(64):data.sha256,historical};},openExternalSummary:()=>{},notice:()=>{}});vm.runInContext('async function restore(entry){const d=entry.data;'+source.slice(start,end)+'}',context);return {data,state,node,inputs,requests,context,restore:keys=>context.restore({kind:'summary',data:{...data,keys:keys??data.keys}})};
}
test('external-summary restoration retains exact artifact and custom selection with fresh approval',async()=>{for(const keys of [[],['custom_owner']]){const h=externalSummaryRestoreHarness();await h.restore(keys);assert.deepEqual(h.requests,[['draft','offer-1']]);assert.deepEqual(h.inputs.filter(i=>i.checked).map(i=>i.value),keys);assert.equal(h.state.preview,null);assert.equal(h.node('summary-confirm').checked,false);assert.equal(h.context.summaryDirty,true);}});
test('external-summary restoration refuses changed, historical or unavailable context',async()=>{for(const options of [{changed:true},{raced:true},{missing:true},{historical:true}]){const h=externalSummaryRestoreHarness(options);await assert.rejects(h.restore());assert.equal(h.context.summaryDirty,false);assert.equal(h.node('recovery-text').hidden,false);assert.ok(h.inputs.every(i=>!i.checked));}});
test('summary PDF refuses changed original context before rendering export bytes',async()=>{const source=fs.readFileSync(new URL('../ui/ui.js',import.meta.url),'utf8'),start=source.indexOf('async function openPdf('),end=source.indexOf("$('report-pdf')",start),context=vm.createContext({clearPdf(){},api:async()=>({project_sha256:'changed'}),selected:'ref',summaryState:{sha256:'original'}});vm.runInContext(source.slice(start,end),context);await assert.rejects(context.openPdf({kind:'summary',keys:['delivery']},'external-summary','Summary'),/project changed/);});

const exportRecoveryBase={folder:'practice',id:'practice',revision:3,sha256:'c'.repeat(64)};
const exportRecoverySelections=[{kind:'report',artifact_id:'',keys:[]},{kind:'report',artifact_id:'',keys:['assumptions']},{kind:'summary',artifact_id:'',keys:[]},{kind:'summary',artifact_id:'offer-1',keys:['custom_owner']},{kind:'document',artifact_id:'',keys:[]},{kind:'document',artifact_id:'offer-1',keys:[]}];
const exportRecoveryInvalid=[{kind:'report',artifact_id:'offer-1',keys:[]},{kind:'report',artifact_id:'',keys:['delivery']},{kind:'summary',artifact_id:'',keys:['delivery']},{kind:'summary',artifact_id:'offer-1',keys:['delivery','delivery']},{kind:'document',artifact_id:'offer-1',keys:['delivery']},{kind:'document',artifact_id:'../other',keys:[]}];

test('export recovery preserves incomplete selections and rejects inconsistent choices or approval',()=>{const a=setup().create('root');for(const selection of exportRecoverySelections){a.write('export-selection',{...exportRecoveryBase,selection});assert.deepEqual(JSON.parse(JSON.stringify(a.read().data.selection)),selection);}for(const selection of exportRecoveryInvalid)assert.throws(()=>a.write('export-selection',{...exportRecoveryBase,selection}));assert.throws(()=>a.write('export-selection',{...exportRecoveryBase,selection:exportRecoverySelections[0],confirmed:true}));});
function exportRestoreHarness({changed=false,raced=false,missing=false,missingDocument=false}={}){
 const source=fs.readFileSync(new URL('../ui/ui.js',import.meta.url),'utf8'),start=source.indexOf(" if(entry.kind==='export-selection'){",source.indexOf('async function applyRecoveredEntry')),end=source.indexOf(" if(entry.kind==='summary'){",start),inputs=[{value:'assumptions',checked:true},{value:'custom_owner',checked:false}],nodes=new Map();
 const node=id=>{if(!nodes.has(id))nodes.set(id,{value:'',hidden:false,checked:true,querySelectorAll:()=>missing?inputs.slice(0,1):inputs});return nodes.get(id);};if(missingDocument)Object.defineProperty(node('exports-document'),'value',{get:()=>'',set(){}});
 const state={view:{sha256:raced?'d'.repeat(64):exportRecoveryBase.sha256},preview:'old',contents:'old'},context=vm.createContext({$:node,projectList:[{folder:'practice',id:'practice',ref:'ref'}],currentView:{revision:changed?4:3,sha256:exportRecoveryBase.sha256},exportState:state,exportDirty:false,show:async()=>{},openExportSettings:async()=>{},exportKind:async()=>{},exportFields:async()=>{},notice:()=>{}});
 const a=source.indexOf('function clearExportReview(){'),b=source.indexOf('\nfunction exportSelection',a);vm.runInContext(source.slice(a,b)+'\nasync function restore(entry){const d=entry.data;'+source.slice(start,end)+'}',context);return {state,node,inputs,context,restore:selection=>context.restore({kind:'export-selection',data:{...exportRecoveryBase,selection}})};
}
test('export restoration preserves exact empty and custom selections and resets review authority',async()=>{for(const selection of exportRecoverySelections){const h=exportRestoreHarness();await h.restore(selection);assert.equal(h.node('exports-kind').value,selection.kind);assert.deepEqual(h.inputs.filter(i=>i.checked).map(i=>i.value),selection.keys);assert.equal(h.state.preview,null);assert.equal(h.state.contents,null);assert.equal(h.node('exports-confirm').checked,false);assert.equal(h.context.exportDirty,true);}});
test('export restoration refuses changed projects, missing documents and missing fields',async()=>{for(const options of [{changed:true},{raced:true},{missing:true},{missingDocument:true}]){const h=exportRestoreHarness(options);await assert.rejects(h.restore(exportRecoverySelections[3]));assert.equal(h.context.exportDirty,false);assert.equal(h.node('recovery-text').hidden,false);}});

const contextRecoveryBase={folder:'practice',id:'practice',revision:3,sha256:'c'.repeat(64),focus:'task-a',depth:'2',exclusions:'  unfinished,\n',fields_ready:false,fields:[]};
const contextRecoveryReady={...contextRecoveryBase,exclusions:'',fields_ready:true,fields:[{record_id:'task-a',field:'title'}]};
const contextRecoveryInvalid=[{confirmed:true},{preview:'old'},{depth:'3'},{exclusions:'x'.repeat(6501)},{fields:[{record_id:'task-a',field:'title'}]},{fields_ready:true,fields:[{record_id:'task-a',field:'title'},{record_id:'task-a',field:'title'}]},{fields_ready:true,fields:[{record_id:'task-a',field:'password'}]}];

test('context recovery retains unfinished raw exclusions and explicit fields without sharing authority',()=>{const a=setup().create('root');for(const value of [contextRecoveryBase,contextRecoveryReady,{...contextRecoveryBase,focus:''}]){a.write('context-selection',value);assert.deepEqual(JSON.parse(JSON.stringify(a.read().data)),value);}for(const patch of contextRecoveryInvalid)assert.throws(()=>a.write('context-selection',{...contextRecoveryBase,...patch}));});
function contextRestoreHarness({changed=false,raced=false,missingFocus=false,missingField=false}={}){
 const source=fs.readFileSync(new URL('../ui/ui.js',import.meta.url),'utf8'),start=source.indexOf(" if(entry.kind==='context-selection'){",source.indexOf('async function applyRecoveredEntry')),end=source.indexOf(" if(entry.kind==='export-selection'){",start),inputs=[{dataset:{record:'task-a'},value:'title',checked:false},{dataset:{record:'task-a'},value:'reason',checked:true}],nodes=new Map();
 const node=id=>{if(!nodes.has(id))nodes.set(id,{value:'',textContent:'',hidden:false,querySelectorAll:()=>missingField?inputs.slice(1):inputs});return nodes.get(id);};
 const state={sha256:raced?'d'.repeat(64):contextRecoveryBase.sha256,choices:missingFocus?[]:[{id:'task-a'}],preview:'old'},calls=[],context=vm.createContext({$:node,projectList:[{folder:'practice',id:'practice',ref:'ref'}],currentView:{revision:changed?4:3,sha256:contextRecoveryBase.sha256},contextState:state,contextDirty:false,show:async()=>{},openContext:async()=>{},chooseContextFields:async()=>{calls.push('fields');},notice:()=>{}});
 const a=source.indexOf('function clearContextPreview(){'),b=source.indexOf('\n',a);vm.runInContext(source.slice(a,b)+'\nasync function restore(entry){const d=entry.data;'+source.slice(start,end)+'}',context);return {state,node,inputs,calls,context,restore:data=>context.restore({kind:'context-selection',data})};
}
test('context restoration keeps incomplete exclusions verbatim without constructing a packet',async()=>{const h=contextRestoreHarness();await h.restore(contextRecoveryBase);assert.equal(h.node('context-exclude').value,contextRecoveryBase.exclusions);assert.equal(h.node('context-depth').value,'2');assert.deepEqual(h.calls,[]);assert.equal(h.state.preview,null);assert.equal(h.node('context-preview').hidden,true);assert.equal(h.context.contextDirty,true);});
test('context restoration includes only original field pairs and removes stale packet text',async()=>{const h=contextRestoreHarness();await h.restore(contextRecoveryReady);assert.deepEqual(h.inputs.map(i=>i.checked),[true,false]);assert.deepEqual(h.calls,['fields']);assert.equal(h.node('context-payload').textContent,'');assert.equal(h.state.preview,null);});
test('context restoration refuses changed projects, missing focus and unavailable fields',async()=>{for(const options of [{changed:true},{raced:true},{missingFocus:true},{missingField:true}]){const h=contextRestoreHarness(options);await assert.rejects(h.restore(contextRecoveryReady));assert.equal(h.context.contextDirty,false);assert.equal(h.node('recovery-text').hidden,false);}});

const restorationDraft={folder:'practice',id:'practice',revision:3,sha256:'c'.repeat(64),snapshot_revision:1,snapshot_sha256:'a'.repeat(64),reason:'  Unfinished reason\n'};
const restorationInvalid=[{confirmed:true},{preview:'old'},{operation_id:'restore-old'},{snapshot_sha256:'bad'},{snapshot_revision:0},{reason:'x'.repeat(3001)}];

test('restoration reason copies preserve original versions and partial input without write authority',()=>{const a=setup().create('root');for(const reason of ['',restorationDraft.reason]){a.write('snapshot-restoration',{...restorationDraft,reason});assert.equal(a.read().data.reason,reason);}for(const patch of restorationInvalid)assert.throws(()=>a.write('snapshot-restoration',{...restorationDraft,...patch}));});
function restorationHarness({changed=false,archived=false,raced=false,missing=false}={}){
 const source=fs.readFileSync(new URL('../ui/ui.js',import.meta.url),'utf8'),start=source.indexOf(" if(entry.kind==='snapshot-restoration'){",source.indexOf('async function applyRecoveredEntry')),end=source.indexOf(" if(entry.kind==='context-selection'){",start),nodes=new Map(),opened=[];
 const node=id=>{if(!nodes.has(id))nodes.set(id,{value:'',textContent:'',hidden:false,checked:true});return nodes.get(id);};
 const state={preview:'old'},context=vm.createContext({$:node,projectList:[{folder:'practice',id:'practice',ref:'ref'}],selected:'ref',currentView:{revision:changed?4:3,sha256:restorationDraft.sha256,archived},restorationState:state,restorationDirty:false,show:async()=>{},openHistory:async()=>({sha256:raced?'d'.repeat(64):restorationDraft.sha256,snapshots:missing?[]:[{revision:1,sha256:restorationDraft.snapshot_sha256,valid:true,ambiguous:false}]}),openSnapshotRestore:(ref,data,item)=>opened.push([ref,item.revision]),notice:()=>{}});
 const a=source.indexOf('function clearRestorationPreview(){'),b=source.indexOf('\n',a);vm.runInContext(source.slice(a,b)+'\nasync function restore(entry){const d=entry.data;'+source.slice(start,end)+'}',context);return {state,node,opened,context,restore:()=>context.restore({kind:'snapshot-restoration',data:restorationDraft})};
}
test('restoration reason recovery reopens exact history but never restores the dossier',async()=>{const h=restorationHarness();await h.restore();assert.deepEqual(h.opened,[['ref',1]]);assert.equal(h.node('restoration-reason').value,restorationDraft.reason);assert.equal(h.node('restoration-confirm').checked,false);assert.equal(h.node('restoration-preview').hidden,true);assert.equal(h.state.preview,null);assert.equal(h.context.restorationDirty,true);});
test('restoration reason recovery refuses changed, archived and missing original context',async()=>{for(const options of [{changed:true},{archived:true},{raced:true},{missing:true}]){const h=restorationHarness(options);await assert.rejects(h.restore());assert.equal(h.context.restorationDirty,false);assert.equal(h.node('recovery-text').hidden,false);assert.deepEqual(h.opened,[]);}});
